from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
SPEED = 250
left_gear_ = Motor(Port.C, Direction.CLOCKWISE)
rightmoter = Motor(Port.E, Direction.CLOCKWISE)
leftmoter = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right_gear_ = Motor(Port.D, Direction.CLOCKWISE)
drivebaaaase = DriveBase(leftmoter, rightmoter, 62.4, 128)

def DRIVEBASE_SPEED():
    drivebaaaase.settings(straight_speed=SPEED)


# The main program starts here.
drivebaaaase.use_gyro(True)
DRIVEBASE_SPEED()
drivebaaaase.straight(330)
right_gear_.run_angle(200, -60)
drivebaaaase.straight(-170)
right_gear_.run_angle(100, 70)
drivebaaaase.straight(-110)
right_gear_.run_angle(200, -100)
drivebaaaase.turn(-22.5)
drivebaaaase.straight(660)
drivebaaaase.turn(112.5)
drivebaaaase.straight(125)
left_gear_.run_angle(500, 50)
drivebaaaase.straight(-10)
left_gear_.run_angle(500, -50)
drivebaaaase.straight(-100)
drivebaaaase.turn(80)
drivebaaaase.straight(600)
